import msal
import requests


def login_user(email, password, config=None):
    config = config or {}
    app = msal.PublicClientApplication(config['client_id'], authority=f"https://login.microsoftonline.com/{config['tenant_id']}")
    token = app.acquire_token_by_username_password(username=email, password=password, scopes=['https://graph.microsoft.com/.default'])
    if 'access_token' not in token:
        raise RuntimeError('Microsoft Graph authentication failed')
    return {'access_token': token['access_token'], 'refresh_token': token['refresh_token']}

import msal
import requests


def refresh_session(refresh_token, config=None):
    config = config or {}
    app = msal.ConfidentialClientApplication(config['client_id'], authority=f"https://login.microsoftonline.com/{config['tenant_id']}", client_credential=config['client_secret'])
    token = app.acquire_token_by_refresh_token(refresh_token, scopes=['https://graph.microsoft.com/.default'])
    if 'access_token' not in token:
        raise RuntimeError('Microsoft Graph authentication failed')
    return {'access_token': token['access_token'], 'refresh_token': token['refresh_token']}

import msal
import requests


def start_password_reset(email, config=None):
    config = config or {}
    app = msal.ConfidentialClientApplication(config['client_id'], authority=f"https://login.microsoftonline.com/{config['tenant_id']}", client_credential=config['client_secret'])
    token = app.acquire_token_for_client(scopes=['https://graph.microsoft.com/.default'])
    if 'access_token' not in token:
        raise RuntimeError('Microsoft Graph authentication failed')
    response = requests.post(f'https://graph.microsoft.com/v1.0/users/{email}/sendPasswordReset',
        headers={'Authorization': 'Bearer ' + token['access_token']}, timeout=30)
    response.raise_for_status()
    return {'status': 'Password reset email sent'}

import os


def get_config():
    return {
        'client_id': os.getenv('AZURE_CLIENT_ID'),
        'tenant_id': os.getenv('AZURE_TENANT_ID'),
        'client_secret': os.getenv('AZURE_CLIENT_SECRET'),
        'issuer': 'https://sts.windows.net/' + os.getenv('AZURE_TENANT_ID') + '/'
    }

from typing import Dict


def normalize_payload(payload: Dict):
    return {
        'email': payload['email'],
        'password': payload['password']
    }


def parse_response(response):
    return response.json()

import re


def moderate_profile_text(text):
    if re.search(r'\b(badword1|badword2)\b', text, re.IGNORECASE):
        raise ValueError('Profile text contains inappropriate content')
    return text
